package org.dextur.reputation.paper;

import java.time.Instant;
import java.util.*;
import java.util.function.Consumer;
import org.bukkit.*;
import org.bukkit.entity.Player;
import org.bukkit.event.*;
import org.bukkit.event.inventory.*;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.inventory.*;
import net.kyori.adventure.text.Component;
import org.dextur.reputation.application.*;
import org.dextur.reputation.domain.investigation.InvestigationData.*;

/** Private inventories with per-section/action permissions, generation checks and one-shot confirmations. */
final class InvestigationGui implements Listener {
    record Layout(int size,Material material,Material confirmation,List<Integer> content,List<Integer> sections,List<Integer> recalculate,int previous,int next,int refresh,int close,int confirm,int cancel){
        static Layout load(java.nio.file.Path directory,int pageSize)throws Exception{var config=TierConfiguration.map(TierConfiguration.configuration(directory,"administration.yml").get("gui"));int size=YamlFiles.number(config,"size",45,54);if(size%9!=0)throw new IllegalArgumentException("INV_GUI");var used=new HashSet<Integer>();var content=slots(config,"content-slots",size,used);var sections=slots(config,"section-slots",size,used);var recalculate=slots(config,"recalculate-slots",size,used);if(content.size()<pageSize||sections.size()!=10||recalculate.size()!=4)throw new IllegalArgumentException("INV_GUI");var buttons=new ArrayList<Integer>();for(String key:List.of("previous-slot","next-slot","refresh-slot","close-slot","confirm-slot","cancel-slot")){int slot=YamlFiles.number(config,key,0,size-1);if(!used.add(slot))throw new IllegalArgumentException("INV_GUI");buttons.add(slot);}return new Layout(size,material(config,"material"),material(config,"confirmation-material"),content,sections,recalculate,buttons.get(0),buttons.get(1),buttons.get(2),buttons.get(3),buttons.get(4),buttons.get(5));}
        private static Material material(Map<String,Object> values,String key){var m=Material.matchMaterial(YamlFiles.text(values,key));if(m==null||!m.isItem()||m.isAir())throw new IllegalArgumentException("INV_GUI");return m;}
        private static List<Integer> slots(Map<String,Object> values,String key,int size,Set<Integer> used){if(!(values.get(key) instanceof List<?> rows))throw new IllegalArgumentException("INV_GUI");var slots=new ArrayList<Integer>();for(Object n:rows){if(!(n instanceof Integer i)||i<0||i>=size||!used.add(i))throw new IllegalArgumentException("INV_GUI");slots.add(i);}return List.copyOf(slots);}
    }
    static final class Session implements InventoryHolder {
        final UUID owner,target;final Section section;final int page;final UUID id;final Map<Integer,Consumer<ClickType>> actions=new HashMap<>();Inventory inventory;boolean busy;long lastClick;Report loaded;Query query;Request confirmation;Instant expires;
        Session(UUID owner,UUID target,Section section,int page,UUID id){this.owner=owner;this.target=target;this.section=section;this.page=page;this.id=id;}
        @Override public Inventory getInventory(){return inventory;}
    }
    private static final List<Section> SECTIONS=List.of(Section.INSPECT,Section.VOTES,Section.PENDING,Section.TRUST,Section.FLAGS,Section.RELATIONS,Section.RECOVERY,Section.ADMIN,Section.AUDIT,Section.RECALCULATE);
    final DexturReputationPlugin plugin;final InvestigationApplication app;final InvestigationCommands commands;final Messages messages;final Layout layout;
    InvestigationGui(DexturReputationPlugin plugin,InvestigationApplication app,InvestigationCommands commands,Messages messages,Layout layout){this.plugin=plugin;this.app=app;this.commands=commands;this.messages=messages;this.layout=layout;}
    private boolean allowed(Player p,Section section){return p.hasPermission("dexturreputation.admin.gui")&&p.hasPermission("dexturreputation.admin."+InvestigationCommands.permission(section));}
    private boolean current(Player p,Session session){return p.isOnline()&&session.owner.equals(p.getUniqueId())&&p.getOpenInventory().getTopInventory().getHolder()==session&&allowed(p,session.section);}
    void open(Player player,UUID target,Section section,int page){open(player,target,section,page,null);}
    private void open(Player p,UUID target,Section section,int page,UUID id){if(!allowed(p,section)){commands.send(p,"no-permission",Map.of());return;}var session=new Session(p.getUniqueId(),target,section,page,id);session.inventory=Bukkit.createInventory(session,layout.size(),messages.content(commands.language(p),"admin7-gui-title",Map.of()));session.query=new Query(section,commands.settings.scope(),section==Section.VOTE?null:target,id,Filter.empty(),page,Math.min(app.rules().pageSize(),section==Section.INSPECT||section==Section.RECALCULATE?layout.content().size()-1:layout.content().size()));p.openInventory(session.inventory);load(p,session);}
    private void load(Player p,Session session){session.busy=true;app.read(session.query).whenComplete((report,error)->plugin.onMain(()->{if(!current(p,session))return;session.busy=false;if(error!=null){commands.failed(p,error);return;}session.loaded=report;render(p,session);}));}
    private ItemStack item(Player p,Material material,String name,List<Component> lore){var item=new ItemStack(material);var meta=item.getItemMeta();meta.displayName(Component.text(name));meta.lore(lore);item.setItemMeta(meta);return item;}
    private void button(Player p,Session s,int slot,Material material,String key,Runnable action){s.inventory.setItem(slot,item(p,material,messages.plain(commands.language(p),key),List.of()));s.actions.put(slot,type->{if(type==ClickType.LEFT)action.run();});}
    private void render(Player p,Session s){s.inventory.clear();s.actions.clear();for(int i=0;i<SECTIONS.size();i++){var section=SECTIONS.get(i);if(allowed(p,section))button(p,s,layout.sections().get(i),layout.material(),"admin7-section-"+section.name().toLowerCase(Locale.ROOT),()->open(p,s.target,section,1));}
        int i=0;var displayed=s.loaded.rows();if(s.section==Section.INSPECT||s.section==Section.RECALCULATE){var combined=new ArrayList<Row>();combined.add(new Row(s.target,s.loaded.summary()));combined.addAll(displayed);displayed=combined;}if(displayed.isEmpty()&&!s.loaded.summary().isEmpty())displayed=List.of(new Row(s.target,s.loaded.summary()));
        for(var row:displayed){if(i>=layout.content().size())break;var lore=new ArrayList<Component>();if(s.section==Section.VOTES||s.section==Section.VOTE)lore.add(messages.content(commands.language(p),"admin7-gui-votes-hint",Map.of()));if(s.section==Section.PENDING)lore.add(messages.content(commands.language(p),"admin7-gui-pending-hint",Map.of()));if(s.section==Section.FLAGS)lore.add(messages.content(commands.language(p),"admin7-gui-flags-hint",Map.of()));for(var e:new TreeMap<>(row.values()).entrySet()){if(e.getKey().equals("plan")||e.getKey().equals("request_hash"))continue;String value=commands.translated(p,e.getValue());if(value.length()>1000)value=value.substring(0,1000)+"…";lore.add(messages.content(commands.language(p),"admin7-field",Map.of("field",commands.label(p,e.getKey()),"value",value)));}int slot=layout.content().get(i++);s.inventory.setItem(slot,item(p,layout.material(),row.id().toString(),lore));
            if(s.section==Section.VOTES)s.actions.put(slot,type->{if(type==ClickType.LEFT&&p.hasPermission("dexturreputation.admin.vote.inspect"))open(p,s.target,Section.VOTE,1,row.id());});
            if(s.section==Section.VOTE&&row.values().containsKey("voter"))s.actions.put(slot,type->{if(type!=ClickType.LEFT)return;var action=row.values().get("status").equals("INVALIDATED")?Action.RESTORE:Action.INVALIDATE;confirm(p,s,commands.request(p,action,row.id(),messages.plain(commands.language(p),"admin7-gui-reason"),Long.parseLong(row.values().get("revision")),""));});
            if(s.section==Section.PENDING)s.actions.put(slot,type->{if(type==ClickType.LEFT||type==ClickType.RIGHT)confirm(p,s,commands.request(p,type==ClickType.LEFT?Action.APPROVE:Action.REJECT,row.id(),messages.plain(commands.language(p),"admin7-gui-reason"),Long.parseLong(row.values().get("revision")),""));});
            if(s.section==Section.FLAGS)s.actions.put(slot,type->{if(type==ClickType.LEFT||type==ClickType.RIGHT)confirm(p,s,commands.request(p,Action.RESOLVE_FLAG,row.id(),messages.plain(commands.language(p),"admin7-gui-reason"),Long.parseLong(row.values().get("revision")),type==ClickType.LEFT?"FALSE_POSITIVE":"CONFIRMED_ABUSE"));});
        }
        if(s.section==Section.RECALCULATE){var actions=List.of(Action.RECALCULATE_REPUTATION,Action.RECALCULATE_TRUST,Action.RECALCULATE_TIER,Action.RECALCULATE_ALL);for(int n=0;n<actions.size();n++){Action action=actions.get(n);if(p.hasPermission("dexturreputation.admin."+InvestigationCommands.permission(action)))button(p,s,layout.recalculate().get(n),layout.confirmation(),"admin7-action-"+action.name().toLowerCase(Locale.ROOT),()->confirm(p,s,commands.request(p,action,s.target,messages.plain(commands.language(p),"admin7-gui-reason"),Long.parseLong(s.loaded.summary().get(action==Action.RECALCULATE_TRUST?"trust_revision":"revision")),"")));}}
        if(s.page>1)button(p,s,layout.previous(),Material.ARROW,"admin7-previous",()->open(p,s.target,s.section,s.page-1,s.id));if((long)s.page*s.query.size()<s.loaded.total())button(p,s,layout.next(),Material.ARROW,"admin7-next",()->open(p,s.target,s.section,s.page+1,s.id));button(p,s,layout.refresh(),Material.CLOCK,"admin7-refresh",()->load(p,s));button(p,s,layout.close(),Material.OAK_DOOR,"gui-close",p::closeInventory);
    }
    private void confirm(Player p,Session origin,Request request){if(!current(p,origin)||!commands.permitted(p,InvestigationCommands.permission(request.action())))return;origin.confirmation=request;origin.expires=app.now().plusSeconds(app.rules().tokenSeconds());origin.inventory.clear();origin.actions.clear();List<Component> lore=List.of(Component.text(request.subject().toString()),Component.text(request.reason()),Component.text(request.operation().toString()));origin.inventory.setItem(layout.confirm(),item(p,layout.confirmation(),messages.plain(commands.language(p),"admin7-confirm-action"),lore));origin.actions.put(layout.confirm(),type->{if(type!=ClickType.LEFT||origin.busy||origin.confirmation==null)return;if(!app.now().isBefore(origin.expires)){commands.failed(p,new IllegalStateException("INV_TOKEN"));open(p,origin.target,origin.section,origin.page,origin.id);return;}if(!commands.permitted(p,InvestigationCommands.permission(request.action())))return;origin.busy=true;origin.confirmation=null;app.read(origin.query).whenComplete((fresh,error)->plugin.onMain(()->{if(!current(p,origin))return;if(error!=null){origin.busy=false;commands.failed(p,error);return;}if(!fresh.fingerprint().equals(origin.loaded.fingerprint())){commands.failed(p,new IllegalStateException("INV_STALE"));open(p,origin.target,origin.section,origin.page,origin.id);return;}commands.mutate(p,request,()->open(p,origin.target,origin.section,origin.page,origin.id));}));});button(p,origin,layout.cancel(),Material.ARROW,"admin7-cancel",()->open(p,origin.target,origin.section,origin.page,origin.id));}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=false)public void click(InventoryClickEvent event){if(!(event.getView().getTopInventory().getHolder() instanceof Session s))return;event.setCancelled(true);if(!(event.getWhoClicked() instanceof Player p)||!current(p,s)||s.busy||!plugin.ready()||event.getRawSlot()<0||event.getRawSlot()>=s.inventory.getSize()||event.getClick()!=ClickType.LEFT&&event.getClick()!=ClickType.RIGHT)return;long now=System.nanoTime();if(now-s.lastClick<250000000L)return;s.lastClick=now;var action=s.actions.get(event.getRawSlot());if(action!=null)action.accept(event.getClick());}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=false)public void drag(InventoryDragEvent event){if(event.getView().getTopInventory().getHolder() instanceof Session)event.setCancelled(true);}
    @EventHandler public void quit(PlayerQuitEvent event){if(event.getPlayer().getOpenInventory().getTopInventory().getHolder() instanceof Session s){s.actions.clear();s.confirmation=null;}}
    void closeAll(){for(var p:plugin.getServer().getOnlinePlayers())if(p.getOpenInventory().getTopInventory().getHolder() instanceof Session s){s.actions.clear();s.confirmation=null;p.closeInventory();}}
}
